const dir=process.argv[2]!,legacyPath=process.argv[3]!;
const {rebuildProjectionsWithReport:legacyReplay}=await import(legacyPath);
const {initializeDatabase:legacyInitialize}=await import(legacyPath.replace('event-log.ts','connection.ts'));
const time='2026-09-28T10:00:00.000Z',edge={id:'shared-edge',source:'synthetic',target:'synthetic-tool',relationship:'uses'};
const batch=ExtractionBatch.fromJSON({version:1,sessionId:'synthetic-session',inputIdentity:'v1:'+'a'.repeat(64),project:'synthetic',provider:'synthetic',model:'synthetic',extractedAt:time,
 result:{added:2,updated:2,superseded:2,skipped:0},facts:[
 {uuid:'beta',type:'preference',content:'synthetic beta',metadata:{graph_edges:[edge]}},
 {uuid:'replace-alpha',type:'supersedence',content:'synthetic replace alpha',metadata:{superseded_uuid:'alpha',superseded_by_uuid:'beta'}},
 {uuid:'gamma',type:'preference',content:'synthetic gamma',metadata:{graph_edges:[edge]}},
 {uuid:'replace-beta',type:'supersedence',content:'synthetic replace beta',metadata:{superseded_uuid:'beta',superseded_by_uuid:'gamma'}}]}).toJSON();
const wrapper=MemoryEventEnvelope.create({eventId:'batch-one',machineId:'synthetic',sequence:30,kind:'projection',operation:'add',occurredAt:new Date(time),observedAt:new Date(time),scope:{project:'synthetic',visibility:'project'},provenance:{source:'memory-extraction',actor:'memory',method:'extraction-batch-v1',sourceIds:['synthetic-session']},privacy:{redactionState:'redacted',containsSensitiveContent:false},consent:{status:'denied',scopes:['local']},causality:{parentEventIds:[],relatedEventIds:[],supersedesEventIds:[]},payload:{extractionBatch:batch}});
const outer=wrapper.toJSON();
const alpha=MemoryEventEnvelope.create({...outer,eventId:'alpha',sequence:20,kind:'preference',occurredAt:new Date(time),observedAt:new Date(time),consent:{status:'not_required',scopes:[]},payload:{fact:{uuid:'alpha',type:'preference',project:'synthetic',content:'synthetic alpha',observedAt:time,metadata:{graph_edges:[edge]}}}});
const effects=expandExtractionBatch(wrapper)!;
const rows:any[]=[];
for(const [reader,replay]of [['v4.0.3',legacyReplay],['current',currentReplay]] as const)for(const mode of['wrapper','flat-relative','flat-reserved']as const){
 const home=join(dir,reader+'-'+mode),events=join(home,'events');mkdirSync(events,{recursive:true});
 const db=new OwnedDatabase(join(home,'synthetic.db'));try{
  createSchema(db);writeFileSync(join(events,'events-a.jsonl'),JSON.stringify(alpha.toJSON())+'\n');
  const children=effects.map((event,index)=>{if(mode!=='flat-reserved')return event;const json=event.toJSON();return MemoryEventEnvelope.create({...json,sequence:31+index,occurredAt:new Date(json.occurredAt),observedAt:new Date(json.observedAt)});});
  const records=mode==='wrapper'?[wrapper]:[wrapper,...children],bytes=records.map(event=>JSON.stringify(event.toJSON())).join('\n')+'\n';
