  renameSync(pending,published);let result,error;const beforeState=db.serialize();
  try{result=await replay(db,undefined,events);}catch(cause){error=String(cause);}
  using facts=db.prepare('SELECT uuid,superseded_by FROM facts WHERE type != ? ORDER BY uuid');
  using governance=db.prepare("SELECT consent_status,source_event_ids FROM memory_governance WHERE surface='graph' AND target_id='shared-edge'");
  rows.push({reader,mode,result,error,facts:facts.all('supersedence'),graphGovernance:governance.get(),publishedBytes:Buffer.byteLength(bytes),preservedOnRefusal:error||result.invalidEvents?db.serialize().equals(beforeState):undefined,sourceUnchanged:readFileSync(published,'utf8')===bytes});
 }finally{db.close();}
}
// A candidate versioned-root boundary: old conventional paths fail, but an
// explicit old-reader override can still bypass it. Do not call this an ACL.
const fenceRoot=join(dir,'fence'),active=join(fenceRoot,'format-2'),events=join(active,'events');mkdirSync(events,{recursive:true});
mkdirSync(join(fenceRoot,'memory.db'));writeFileSync(join(fenceRoot,'events'),'Synthetic legacy path retired; no production migration.');
writeFileSync(join(events,'events-a.jsonl'),[alpha,wrapper].map(e=>JSON.stringify(e.toJSON())).join('\n')+'\n');
let databaseError;try{const opened=legacyInitialize({path:join(fenceRoot,'memory.db')});opened.db.close();}catch(error){databaseError=String(error);}
const protectedDb=new OwnedDatabase(join(active,'memory.db'));try{
 createSchema(protectedDb);await currentReplay(protectedDb,undefined,events);const before=protectedDb.serialize();
 let sourceError;try{await legacyReplay(protectedDb,undefined,join(fenceRoot,'events'));}catch(error){sourceError=String(error);}
 const preserved=protectedDb.serialize().equals(before);assert(databaseError);assert(sourceError);assert(preserved);
 await legacyReplay(protectedDb,undefined,events);using count=protectedDb.prepare('SELECT uuid FROM facts ORDER BY uuid');const bypassFacts=count.all();
 assert.deepEqual(bypassFacts,[{uuid:'alpha'}]);rows.push({reader:'v4.0.3',mode:'legacy-path-fence',databaseError,sourceError,preservedOnRefusal:preserved,explicitOverrideBypassFacts:bypassFacts});
}finally{protectedDb.close();}
writeFileSync(join(dir,'results.json'),JSON.stringify(rows,null,2));console.log(JSON.stringify(rows));
const find=(reader:string,mode:string)=>rows.find(r=>r.reader===reader&&r.mode===mode);
assert.equal(find('v4.0.3','wrapper').facts.length,1);
assert.equal(find('v4.0.3','flat-relative').facts.find((r:any)=>r.uuid==='alpha').superseded_by,null);
assert.equal(find('v4.0.3','flat-reserved').facts.find((r:any)=>r.uuid==='alpha').superseded_by,'beta');
assert.equal(find('v4.0.3','flat-reserved').graphGovernance.consent_status,'not_required');
assert.equal(find('current','wrapper').graphGovernance.consent_status,'denied');
assert.equal(find('current','flat-relative').result.invalidEvents,4);assert.equal(find('current','flat-relative').preservedOnRefusal,true);
assert.equal(find('current','flat-reserved').result.invalidEvents,4);assert.equal(find('current','flat-reserved').preservedOnRefusal,true);

